START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM petwork."__EFMigrationsHistory" WHERE "MigrationId" = '20260909111021_AddAdoptionAndProductReviews') THEN
    CREATE TABLE petwork."AdoptionListings" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "PetName" character varying(50) NOT NULL,
        "Species" character varying(50) NOT NULL,
        "Breed" character varying(100),
        "AgeYears" integer,
        "Gender" character varying(20),
        "City" character varying(80) NOT NULL,
        "District" character varying(80),
        "HealthInfo" character varying(500) NOT NULL,
        "Story" character varying(2000) NOT NULL,
        "ImagePath" character varying(500) NOT NULL,
        "Status" character varying(20) NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        "IsDeleted" boolean NOT NULL,
        CONSTRAINT "PK_AdoptionListings" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AdoptionListings_Users_UserId" FOREIGN KEY ("UserId") REFERENCES petwork."Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

