        "PetType" character varying(50) NOT NULL,
        "Experience" character varying(1500) NOT NULL,
        "TasteScore" integer NOT NULL,
        "IngredientScore" integer NOT NULL,
        "DigestionScore" integer NOT NULL,
        "ValueScore" integer NOT NULL,
        "ImagePath" character varying(500),
        "CreatedAt" timestamp without time zone NOT NULL,
        "IsDeleted" boolean NOT NULL,
        CONSTRAINT "PK_ProductReviews" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ProductReviews_Users_UserId" FOREIGN KEY ("UserId") REFERENCES petwork."Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

